// We wrap everything in verus! so that the Verus verifier is active.
verus! {

    // Import the persistent Vec and its indexing operations
    use pervasive::vec::Vec;

    /// Given an input vector `c : Vec<f64>`, returns a new vector
    /// whose length is exactly one greater than `c.len()`,
    /// whose first element is 0.0, and which shifts every element
    /// of `c` one position to the right.
    ///
    /// Requires: nothing (any Vec has nonnegative length).
    /// Ensures:
    ///   - the result has length `c.len() + 1`
    ///   - `result[0] == 0.0`
    ///   - for all `i < c.len()`, `result[i+1] == c[i]`
    pub fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
        ensures
            // the new vector is exactly one longer
            result.len() == c.len() + 1
            // the 0-th slot is 0.0
            && result.index(0) == 0.0
            // and every old element is shifted right by one
            && (forall |i: usize| i < c.len() ==> result.index(i + 1) == c.index(i))
    {
        // allocate capacity
        let mut result = Vec::with_capacity(c.len() + 1);
        // set the first element
        result.push(0.0);

        // now shift each element of `c` one slot to the right
        let mut i: usize = 0;
        while i < c.len() {
            // *** LOOP INVARIANTS ***
            // 1) i never overshoots c.len()
            invariant i <= c.len();
            // 2) result.len() always equals i+1
            //    (we have pushed exactly i+1 elements so far)
            invariant result.len() == i + 1;
            // 3) for all j < i, we already have
            //    result[j+1] == c[j]
            invariant forall |j: usize| j < i
                ==> result.index(j + 1) == c.index(j);
            // *** DECREASES CLAUSE ***
            // ensures termination
            decreases c.len() - i;

            // body: push the next element of c
            result.push(c.index(i));
            i += 1;
        }

        result
    }

} // end verus!